// A feature pull request must not carry generated registry output.
//
//   node apps/registry/scripts/check-no-generated-output.mjs <base ref>
//
// The registry output under apps/registry/public (r/, data/, .well-known/, tokens/, llms*.txt)
// is rebuilt from source. Committed in a feature PR it conflicts with every other PR that
// touches it, whenever main moves, and GitHub's "Update branch" ignores the merge driver that
// used to paper over that. So a feature PR commits sources only; the output is regenerated by
// every build and deploy, and committed once, in the release (Version Packages) commit, which
// is the only branch exempt from this check (the workflow skips it for `changeset-release/*`).
//
// Exit 1 lists the generated files the PR changed against its merge base and says how to put
// them back. Exit 0 means the diff holds sources only.

import { execFileSync } from 'node:child_process';

import { isGenerated } from './lib/generated-paths.mjs';

const base = process.argv[2];
if (!base) {
  console.error('usage: node check-no-generated-output.mjs <base ref>');
  process.exit(2);
}

const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim();
const mergeBase = git('merge-base', base, 'HEAD');
const changed = git('diff', '--name-only', mergeBase, 'HEAD')
  .split('\n')
  .filter(Boolean)
  .filter(isGenerated);

if (changed.length === 0) {
  console.log('check-no-generated-output: the diff holds sources only.');
} else {
  console.error(
    `This pull request changes ${changed.length} generated registry file(s):\n\n` +
      changed.map((f) => `  ${f}`).join('\n') +
      '\n\nGenerated output is committed by the release, never by a feature PR (it conflicts with\n' +
      'every other PR whenever main moves). A local build rewrites these files; do not stage them.\n' +
      'Put them back and push:\n\n' +
      `  git checkout ${mergeBase} -- apps/registry/public\n` +
      `  git diff --name-only --diff-filter=A ${mergeBase} HEAD -- apps/registry/public | xargs -r git rm -q\n` +
      '  git commit -m "chore(registry): leave generated output to the release"\n',
  );
  process.exit(1);
}
